//! 🧪️ Actual donated MeasureValue controller exposes exact INTEGER, NUMBER and fixed ARRAY fields.
use super::*;
use semio_framework_plugin::{AppRenderOperationContext,ChildContentView};
use semio_framework_ui_contract::{Component,OriginalBuiltTreeRetirement};
use semio_s_artifact_stdio_ifc_4_model::standards::v4::subsets::any::schema::snapshot::{IfcEntity,IfcComplexType,IfcTypedValue};
fn value(row:&serde_json::Value)->IfcValue{match row["kind"].as_str().unwrap(){"unset"=>IfcValue::Unset,"string"=>IfcValue::String(row["value"].as_str().unwrap().into()),"integer"=>IfcValue::Integer(row["value"].as_str().unwrap().parse().unwrap()),"reference"=>IfcValue::Reference(row["value"].as_str().unwrap().parse().unwrap()),"real"=>IfcValue::Real(f64::from_bits(row["value"]["bits"].as_str().unwrap().parse().unwrap())),"aggregate"=>IfcValue::Aggregate(row["value"].as_array().unwrap().iter().map(value).collect()),"typedValue"=>IfcValue::TypedValue(IfcTypedValue{name:row["value"]["name"].as_str().unwrap().into(),items:row["value"]["items"].as_array().unwrap().iter().map(value).collect()}),_=>panic!("closed source vector")}}
#[test]
fn donated_measure_select_controller_keeps_complete_choices_explicit_representations_and_original_words(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../🔎️details/🧪️tests/type-measure-select-input.json")).unwrap();for row in law["cases"].as_array().unwrap(){let snapshot=std::sync::Arc::new(IfcSnapshot{entities:law["source"]["entities"].as_array().unwrap().iter().map(|entity|IfcEntity{id:entity["id"].as_str().unwrap().parse().unwrap(),name:entity["name"].as_str().unwrap().into(),args:entity["args"].as_array().unwrap().iter().map(value).collect(),complex:entity["complex"].as_array().unwrap().iter().map(|part|IfcComplexType{name:part["name"].as_str().unwrap().into(),args:part["args"].as_array().unwrap().iter().map(value).collect()}).collect()}).collect(),..Default::default()});let history=semio_framework_plugin::HistoryView::empty();let view=staged_view();let operation=AppRenderOperationContext{app_instance_id:17,base_revision:semio_framework_job::RevisionId(0),generation:semio_framework_job::Generation(1),canonical_base_revision:[0;32],mounted_policy:semio_framework_plugin::app_testing::artifact_app_laws::fixture_mounted_policy()};let doc=semio_framework_async::poll::resolve_ready(ArtifactView::with_render_context(snapshot.as_ref(),&history,ChildContentView::EMPTY,operation,"actual-measure-source",None));let mut caller=OriginalWorkFixture::new();let mut work=caller.work_turn(staged_grant(),1000,|cx|Ifc4x3AnyEditor::begin_render_work(semio_framework_plugin::action_staging::STAGED_FORM_BODY_KEY,cx)).unwrap().unwrap();let rows=if row["items"].is_null(){serde_json::json!([])}else{serde_json::json!([{"index":"0","value":{"kind":"typedValue","value":{"name":row["member"],"items":row["items"]}}},{"index":"1","value":{"kind":"typedValue","value":{"name":row["member"],"items":row["items"]}}}])};let mut request=staged_request(&serde_json::json!({"path":"/entities/0","value":{"$ifcType":law["entity"],"$ifcInputs":rows}}));request.token.action=editing::SET_SNAPSHOT_VALUE_ACTION_ID.into();let mut donor=Some(request);for _ in 0..16{if caller.work_turn(staged_grant(),1000,|cx|Ifc4x3AnyEditor::receive_render_work_request(&mut work,&mut donor,&view,cx)).unwrap().is_some(){break;}}assert!(donor.is_none());let mut output=None;for turn in 0..1000000{match caller.work_turn(staged_grant(),1000,|cx|Ok(work.render(semio_framework_plugin::action_staging::STAGED_FORM_BODY_KEY,&snapshot,&doc,&view,cx))).unwrap(){Ok(Some(tree))=>{output=Some(tree);break;},Ok(None)=>{},Err(_)=>panic!("Measure draft remains editable: {}",row["id"])}assert!(turn<999999);}let tree=output.unwrap();let Component::Extension(status)=&tree.root.children.get(0).unwrap().component else{panic!("original readiness")};assert_eq!(serde_json::to_value(&status.props).unwrap()["ready"],row["ready"]);let fields=tree.root.children.iter().skip(1).collect::<Vec<_>>();let mut offset=0;for _ in 0..2{let node=fields[offset].children.get(0).unwrap();let Component::Select(select)=&node.component else{panic!("complete Measure member discriminator")};assert_eq!(select.items.len(),23);assert!(!node.bindings.is_empty());offset+=1;if row["items"].is_null(){continue;}let items=row["items"].as_array().unwrap();let node=fields[offset].children.get(0).unwrap();assert!(!node.bindings.is_empty());if row["member"]=="IFCNUMERICMEASURE"{let Component::Select(select)=&node.component else{panic!("explicit NUMBER representation")};assert_eq!(select.items.len(),2);assert_eq!(select.value.as_ref(),items.first().map_or("",|child|child["kind"].as_str().unwrap()));offset+=1;if !items.is_empty(){let node=fields[offset].children.get(0).unwrap();let Component::Input(input)=&node.component else{panic!("exact numeric word")};let raw=if items[0]["kind"]=="real"{items[0]["value"]["bits"].as_str().unwrap()}else{items[0]["value"].as_str().unwrap()};assert_eq!(input.value.as_ref(),raw);offset+=1;}}else if row["member"]=="IFCCOMPLEXNUMBER"{assert!(matches!(&node.component,Component::Button(_)));offset+=1;if let Some(members)=items.first().and_then(|child|child["value"].as_array()){for member in members{let node=fields[offset].children.get(0).unwrap();let Component::Input(input)=&node.component else{panic!("ARRAY REAL member")};assert_eq!(input.value.as_ref(),member["value"]["bits"].as_str().unwrap());assert!(matches!(&fields[offset+1].children.get(0).unwrap().component,Component::Button(_)));offset+=2;}}}else{let Component::Input(input)=&node.component else{panic!("exact scalar word")};let raw=items.first().map_or("",|child|if child["kind"]=="real"{child["value"]["bits"].as_str().unwrap()}else{child["value"].as_str().unwrap()});assert_eq!(input.value.as_ref(),raw);offset+=1;}}assert_eq!(offset,fields.len());let mut close=OriginalBuiltTreeRetirement::new(tree.root);for _ in 0..1000000{if close.terminal_is_empty(){break;}caller.turn(staged_grant(),|cx|cx.with_original_retirement(|cx|{let demand=close.next_demand(32768)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|close.step(grant))?;Ok(())})).unwrap();}assert!(close.terminal_is_empty());caller.cancel().cancel_now();retire_staged(&mut caller,&mut Some(work));assert_eq!(std::sync::Arc::strong_count(&snapshot),1);caller.finish();}
}
